/* @lc app=leetcode id=2101 lang=kotlin */ class Solution { fun maximumDetonation(bombs: Array<IntArray>): Int = bombs.indices.map { i -> bombs.indices.filter { j -> (bombs[i][0] - bombs[j][0]).toLong() * (bombs[i][0] - bombs[j][0]) + (bombs[i][1] - bombs[j][1]).toLong() * (bombs[i][1] - bombs[j][1]) <= bombs[i][2].toLong() * bombs[i][2] } }.let { adj -> bombs.indices.maxOf { s -> HashSet<Int>().also { it.add(s) }.let { seen -> generateSequence(listOf(s)) { f -> f.flatMap { adj[it] }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.flatten().count() } } } }